--- a/node/safe-merge/index.mjs
+++ b/node/safe-merge/index.mjs
@@ -1,3 +1,58 @@
+const FORBIDDEN_KEYS = new Set(["__proto__", "prototype", "constructor"]);
+
+function isPlainObject(value) {
+  if (typeof value !== "object" || value === null || Array.isArray(value)) {
+    return false;
+  }
+  const proto = Object.getPrototypeOf(value);
+  return proto === Object.prototype || proto === null;
+}
+
+function deepClone(value) {
+  if (Array.isArray(value)) {
+    return value.map(deepClone);
+  }
+  if (value !== null && typeof value === "object") {
+    if (value instanceof Date) {
+      return new Date(value.getTime());
+    }
+    const proto = Object.getPrototypeOf(value);
+    const clone = Object.create(proto);
+    for (const key of Object.keys(value)) {
+      if (FORBIDDEN_KEYS.has(key)) continue;
+      clone[key] = deepClone(value[key]);
+    }
+    return clone;
+  }
+  return value;
+}
+
 export function safeMerge(base, patch) {
-  return { ...base, ...patch };
+  const baseObj = isPlainObject(base) ? base : {};
+  const patchObj = isPlainObject(patch) ? patch : {};
+  const keys = new Set([...Object.keys(baseObj), ...Object.keys(patchObj)]);
+  const result = {};
+
+  for (const key of keys) {
+    if (FORBIDDEN_KEYS.has(key)) continue;
+
+    const inBase = Object.prototype.hasOwnProperty.call(baseObj, key);
+    const inPatch = Object.prototype.hasOwnProperty.call(patchObj, key);
+
+    if (inBase && inPatch) {
+      const baseValue = baseObj[key];
+      const patchValue = patchObj[key];
+      if (isPlainObject(baseValue) && isPlainObject(patchValue)) {
+        result[key] = safeMerge(baseValue, patchValue);
+      } else {
+        result[key] = deepClone(patchValue);
+      }
+    } else if (inPatch) {
+      result[key] = deepClone(patchObj[key]);
+    } else {
+      result[key] = deepClone(baseObj[key]);
+    }
+  }
+
+  return result;
 }
